06\u91cf\u4e3a top TICA \u5206\u91cf\u3002\n- **\u4f30\u8ba1\u6570\u636e\uff08\u5173\u952e\u8bbe\u8ba1\uff09**\uff1a**\u53ea\u5728\u771f\u5b9e MD \u53c2\u8003\u8f68\u8ff9\u4e0a\u4f30\u8ba1**\u2014\u2014\u51bb\u7ed3\u5747\u503c\u5411\u91cf \u03bc \u4e0e\u6295\u5f71\u77e9\u9635 U\uff08\u524d k \u4e2a\u7279\u5f81\u5411\u91cf\uff09\uff0c\u518d\u628a MD \u4e0e\u6b63\u5411\u4eff\u771f\u5e27\u90fd\u7ecf\u540c\u4e00\u7ebf\u6027\u6620\u5c04\u6295\u5f71\u5230\u5206\u91cf\u7a7a\u95f4 (IC\u2081,\u2026,IC\u2096)\u3002\n- **\u53c2\u6570\u5047\u8bbe\uff08A4\u2013A6\uff09**\uff1a\u7279\u5f81\u8f93\u5165\u9ed8\u8ba4\u7528\u5168\u90e8\u4e3b\u94fe+\u4fa7\u94fe\u4e8c\u9762\u89d2\u7684 sin/cos \u5d4c\u5165\uff08\u5907\u9009\uff1a\u91cd\u539f\u5b50\u4e24\u4e24\u8ddd\u79bb\uff09\uff1b\u65f6\u6ede \u03c4 \u9ed8\u8ba4\u53d6 MD \u8f93\u51fa\u6b65\u957f\u7684\u82e5\u5e72\u500d\u5e76\u505a\u654f\u611f\u6027\u68c0\u67e5\uff1b\u5206\u91cf\u6570 k \u9ed8\u8ba4 2\u20133\uff0c\u4f9d\u636e\u7279\u5f81\u503c\u7f3a\u53e3/\u7d2f\u8ba1\u52a8\u80fd\u65b9\u5dee\u9009\u62e9\u3002\n- **\u7406\u7531**\uff1a\u53ea\u6709\u5171\u4eab\u540c\u4e00\u5750\u6807\u7cfb\uff08\u540c\u4e00 \u03bc\u3001\u540c\u4e00\u6295\u5f71\u77e9\u9635\uff09\uff0cIC\u2081..IC\u2096 \u624d\u80fd\u5728\u4e24\u4fa7\u9010\u5206\u91cf\u53ef\u6bd4\uff1b\u201c\u5404\u81ea\u4f30\u8ba1\u201d\u4f1a\u4ea7\u751f\u4e0d\u540c\u5750\u6807\u7cfb\uff0c\u5c5e\u82f9\u679c\u4e0e\u6a58\u5b50\u6bd4\u8f83\u3002\n\n---\n\n## 3. \u9010\u6b65\u8bbe\u8ba1 rationale\uff08\u6bcf\u6b65\u7684\u7406\u7531\uff09\n1. **\u5e27\u6c60\u5316\u4e3a\u4e24\u7ec4\u7ecf\u9a8c\u6837\u672c**\uff1a\u95ee\u9898\u7684\u63d0\u6cd5\u662f\u201c\u5206\u5e03\u76f8\u4f3c\u6027\u201d\uff0c\u8003\u5bdf\u91c7\u6837\u8986\u76d6\u7684\u5e73\u7a33\u5206\u5e03\uff0c\u6545\u628a\u4e24\u4fa7\u6240\u6709\u91c7\u6837\u5e27\u6c60\u5316\uff1b\u5185\u90e8\u5750\u6807\u5929\u7136\u65e0\u9700\u7ed3\u6784\u5bf9\u9f50\uff1b\u524d\u63d0\u662f\u4e24\u65b9\u5171\u4eab\u540c\u4e00\u62d3\u6251/\u539f\u5b50\u547d\u540d\uff08\u5047\u8bbe A8\uff09\uff0c\u4fdd\u8bc1\u540c\u5e8f\u53f7\u626d\u8f6c\u4e00\u4e00\u5bf9\u5e94\u3002\n2. **\u72ec\u7acb\u6027\u95ee\u9898**\uff1a\u8f68\u8ff9\u5185\u5e27\u5f3a\u81ea\u76f8\u5173\u4f1a\u4f7f\u201c\u6709\u6548\u6837\u672c\u91cf\u201d\u5c0f\u4e8e\u5e27\u6570\uff0c\u5bfc\u81f4\u68c0\u9a8c\u529f\u6548\u865a\u9ad8\u3002\u2192 \u4f30\u8ba1\u6ede\u540e\u81ea\u76f8\u5173/\u6709\u6548\u6837\u672c\u91cf\uff0c\u5fc5\u8981\u65f6\u6309\u76f8\u5173\u65f6\u95f4\u53bb\u7c97\uff08thinning\uff09\uff0c\u5e76\u7528\u5757\u81ea\u4e3e\uff08block bootstrap\uff09\u7ed9\u51fa\u6307\u6807\u4f30\u8ba1\u7684\u7f6e\u4fe1\u533a\u95f4\u3002\n3. **\u6307\u6807\u9009\u578b**\uff1a\u626d\u8f6c\u89d2\u662f\u5468\u671f\u6570\u636e \u2192 \u7528\u5faa\u73af\u76f4\u65b9\u56fe/\u5faa\u73af KDE + JSD\uff08\u6709\u754c [0,1]\uff09\u3001\u5706\u4e0a Wasserstein\uff08\u6709\u754c \u2264\u03c0\uff09\u3001KLD\uff08\u65e0\u754c\uff0c\u4f5c\u6b21\u8981\u6307\u6807\uff09\uff1bTICA \u5206\u91cf\u8fd1\u4f3c\u7ebf\u6027\u975e\u5468\u671f \u2192 \u7528 KS\u3001Energy distance / MMD\u30012D \u76f4\u65b9\u56fe JSD\u3002JSD \u4e3a\u4e3b\u6807\u91cf\u3001Wasserstein \u4e3a\u51e0\u4f55\u8ddd\u79bb\u3001\u68c0\u9a8c\u7edf\u8ba1\u91cf\u4e3a\u63a8\u65ad\uff08\u7ed3\u5408\u6548\u5e94\u91cf\uff09\u3002\n4. **TICA \u4f30\u8ba1/\u8bc4\u4f30\u5206\u79bb**\uff1a\u03bc\u3001U\u3001k\u3001\u03c4 \u5168\u90e8\u53ea\u7531 MD \u53c2\u8003\u96c6\u51b3\u5b9a\u5e76\u51bb\u7ed3\uff0c\u7edd\u4e0d\u4f7f\u7528\u6b63\u5411\u4eff\u771f\u5e27\u53c2\u4e0e\u4f30\u8ba1\uff0c\u4e5f\u7edd\u4e0d\u9488\u5bf9\u6bd4\u8f83\u7ed3\u679c\u8c03\u53c2\u2014\u2014\u907f\u514d\u4fe1\u606f\u6cc4\u6f0f\u4e0e\u8fc7\u62df\u5408\u3002\n5. **\u201c\u76f8\u4f3c\u201d\u7684\u64cd\u4f5c\u542b\u4e49**\uff1a\u6587\u4ef6\u65e0\u9884\u8bbe\u9608\u503c \u2192 \u7528\u63a7\u5236\u63aa\u65bd\u6807\u5b9a\uff08\u89c1 \u00a74\uff09\u3002\n\n---\n\n## 4. \u63a7\u5236\u63aa\u65bd\n- **C1 \u00b7 MD \u81ea\u5206\u534a\u81ea\u76f8\u4f3c\u57fa\u7ebf**\uff1a\u628a MD \u5e27\u968f\u673a\u7b49\u5206\u4e3a\u4e24\u534a\uff0c\u7528\u540c\u4e00\u5957\u7ba1\u7ebf\u8ba1\u7b97\u5168\u90e8\u6307\u6807\uff0c\u5f97\u5230\u201c\u540c\u4e00\u5206\u5e03\u5185\u90e8\u7684\u53ef\u8fbe\u76f8\u4f3c\u6c34\u5e73\u201d\u53c2\u8003\u5206\u5e03\uff08\u542b\u6ce2\u52a8\u533a\u95f4\uff09\u3002\n- **C2 \u00b7 \u6d17\u724c\u5931\u914d\u5bf9\u7167**\uff1a\u628a\u626d\u8f6c\u503c\u5728\u5e27\u95f4\u968f\u673a\u7f6e\u6362/\u6d17\u724c\uff08\u6253\u4e71\u8054\u5408\u7ed3\u6784\u4e0e\u5206\u5e03\uff09\uff0c\u7528\u540c\u4e00\u7ba1\u7ebf\u8ba1\u7b97\u6307\u6807\uff0c\u7ed9\u51fa\u201c\u660e\u663e\u4e0d\u76f8\u4f3c\u201d\u7684\u4e0a\u754c\u53c2\u8003\u3002\n- **C3 \u00b7 TICA \u4f30\u8ba1/\u8bc4\u4f30\u6570\u636e\u5206\u79bb**\uff1a\u03bc\u3001U\u3001k\u3001\u03c4 \u4ec5\u7531 MD \u53c2\u8003\u96c6\u4f30\u8ba1\u5e76\u51bb\u7ed3\uff1b\u6b63\u5411\u4eff\u771f\u6570\u636e\u7edd\u4e0d\u53c2\u4e0e TICA \u4f30\u8ba1\u4e0e\u53c2\u6570\u9009\u62e9\u3002\n- **C4 \u00b7 \u591a\u91cd\u6bd4\u8f83\u6821\u6b63**\uff1a\u6240\u6709\u9010 CV \u4e24\u6837\u672c\u68c0\u9a8c\u8de8\u68c0\u9a8c\u6570\u505a Benjamini\u2013Hochberg FDR \u6821\u6b63\uff08\u03b1=0.05\uff09\u3002\n\n---\n\n## 5. \u5b8c\u6574\u5206\u6790\u8ba1\u5212\n\n### 5.1 \u6240\u9700\u8f93\u5165\u4e0e\u73af\u5883\uff08\u5f53\u524d\u7f3a\u5931\uff0c\u6807\u6ce8\uff09\n- **\u5fc5\u9700\u8f93\u5165\uff08\u5747\u4e3a\u5047\u8bbe A3/A7/A8\uff09**\uff1a\u2460 \u771f\u5b9e MD \u8f68\u8ff9\u5e27 + \u62d3\u6251/PDB\uff08\u683c\u5f0f\u5982 xtc/dcd + pdb\uff09\uff1b\u2461 \u6b63\u5411\u4eff\u771f\u91c7\u6837\u5e27\uff08\u5047\u5b9a\u76f8\u540c\u62d3\u6251\u3001\u76f8\u540c\u5355\u4f4d\u4e0e\u6e29\u5ea6/\u529b\u573a\u8bbe\u7f6e\uff0cA7\uff09\uff1b\u2462 \u4e24\u8005\u5e27\u6570\u4e0e\u8f68\u8ff9\u6570\u3002\n- **\u6240\u9700\u4f9d\u8d56\u5e93\uff08\u5f53\u524d\u5168\u90e8\u7f3a\u5931\uff09**\uff1anumpy\u3001scipy\u3001mdtraj \u6216 mdanalysis\uff08\u8bfb\u8f68\u8ff9+\u7b97\u626d\u8f6c\uff09\u3001deeptime \u6216\u624b\u5199 TICA\u3001scikit-learn\uff08\u53ef\u9009\uff09\u3001matplotlib\uff08\u8bca\u65ad\u56fe\uff09\u3002network \u7981\u7528 \u2192 \u82e5\u5c06\u6765\u8981\u6267\u884c\u9700\u79bb\u7ebf\u8f6e\u5b50\u4f9b\u7ed9\uff08vendor wheel\uff09\uff0c\u5217\u5165\u53ef\u884c\u6027\u7ea6\u675f\u3002\n\n### 5.2 \u7ba1\u7ebf\u6b65\u9aa4\n1. \u88c5\u8f7d\u62d3\u6251\u4e0e\u4e24\u4fa7\u5e27\u96c6\uff1b\u6821\u9a8c\u6b8b\u57fa\u5e8f\u5217\u4e0e\u539f\u5b50\u547d\u540d\u4e00\u81f4\uff1b\u6784\u5efa\u539f\u5b50\u2192\u626d\u8f6c\u6620\u5c04\u3002\n2. \u8ba1\u7b97\u4e3b\u94fe \u03c6/\u03c8\u3001\u4fa7\u94fe \u03c7\uff08\u6309\u6b8b\u57fa\uff09\uff0c\u7edf\u4e00\u6298\u5165 [-\u03c0,\u03c0]\u3002\n3. TICA \u7279\u5f81\u5316\uff08\u9ed8\u8ba4 sin/cos \u5168\u90e8\u626d\u8f6c\uff09\u2192 \u4ec5\u5728 MD \u53c2\u8003\u5e27\u4e0a\u4f30\u8ba1 TICA\uff08\u03bc\u3001U\u3001\u03c4\u3001k\uff09\u2192 \u51bb\u7ed3\u540e\u6295\u5f71\u4e24\u4fa7\u3002\n4. \u9010\u626d\u8f6c\u89d2\uff1a\u5faa\u73af\u76f4\u65b9\u56fe\uff0836 bin\u00d710\u00b0\uff09\u2192 JSD\u3001\u5706\u4e0a Wasserstein\u3001\u5faa\u73af KDE-KLD\u3001Kuiper \u6216 Watson U\u00b2 \u68c0\u9a8c\uff08BH \u6821\u6b63\uff09\u3002\n5. TICA\uff1a\u9010\u5206\u91cf 1D KS \u4e0e Energy distance/MMD\uff1b\u5bf9 (IC\u2081,IC\u2082) \u505a 2D \u76f4\u65b9\u56fe JSD\u3002\n6. \u7528\u540c\u4e00\u7ba1\u7ebf\u8ba1\u7b97 C1 \u81ea\u76f8\u4f3c\u57fa\u7ebf\u4e0e C2 \u5931\u914d\u5bf9\u7167\u3002\n7. \u81ea\u76f8\u5173\u5904\u7406\uff1a\u4f30\u8ba1\u6709\u6548\u6837\u672c\u91cf\u3001\u5fc5\u8981\u65f6 thinning\uff1b\u5757\u81ea\u4e3e\u7ed9\u51fa\u6240\u6709\u6307\u6807\u7684\u7f6e\u4fe1\u533a\u95f4\u3002\n8. \u5224\u5b9a\u4e0e\u6c47\u62a5\uff1a\u8f93\u51fa\u9010 CV \u8868\uff08JSD/Wasserstein/KLD/\u68c0\u9a8c p \u503c\uff0c\u542b CI \u4e0e\u6821\u6b63\u6807\u8bb0\uff09+ \u6bcf\u7c7b CV \u7684\u7efc\u5408\u7ed3\u8bba + \u8bca\u65ad\u56fe\uff08\u76f4\u65b9\u56fe\u8986\u76d6\u3001Ramachandran\u3001TICA \u6563\u70b9\u3001\u7279\u5f81\u503c\u8c31\uff09\u3002\n\n### 5.3 \u5224\u5b9a\u51c6\u5219\uff08\u660e\u786e\u4e3a\u8bbe\u8ba1\u51b3\u5b9a\uff0c\u975e\u6587\u4ef6\u89c4\u5b9a\uff09\n- \u7ed3\u8bba\u5224\u4e3a\u201c\u5206\u5e03\u76f8\u4f3c\u201d\u5f53\u4e14\u4ec5\u5f53\uff1a**\u8be5\u7c7b CV \u7684\u6307\u6807\u843d\u5165 MD \u81ea\u5206\u534a\u57fa\u7ebf\u5e26\uff08\u81ea\u76f8\u4f3c\u6ce2\u52a8\u8303\u56f4\uff09\u5185\uff0c\u4e14\u660e\u663e\u8fdc\u79bb\u6d17\u724c\u5931\u914d\u5bf9\u7167**\uff0c\u5e76\u540c\u65f6\u62a5\u544a\u6548\u5e94\u91cf\u3002**\u4e0d\u5355\u72ec\u4ee5 p<0.05 \u5224\u5b9a**\uff08p \u503c\u53d7\u6837\u672c\u91cf\u652f\u914d\uff1b\u201c\u663e\u8457\u6027\u2260\u76f8\u4f3c\u6027\u201d\uff09\uff1bBH \u6821\u6b63\u540e\u7684\u68c0\u9a8c\u7ed3\u679c\u4ec5\u4f5c\u652f\u6491\u6027\u8bc1\u636e\u3002\n- \u82e5\u67d0 CV \u4ecb\u4e8e\u57fa\u7ebf\u4e0e\u5bf9\u7167\u4e4b\u95f4 \u2192 \u5224\u201c\u90e8\u5206\u76f8\u4f3c/\u4e0d\u786e\u5b9a\u201d\uff0c\u9010\u7c7b\u6c47\u62a5\u800c\u975e\u4e8c\u5143\u63a9\u76d6\u3002\n\n---\n\n## 6. \u5047\u8bbe\u6e05\u5355\uff08\u6240\u6709\u672a\u5728\u6587\u4ef6\u4e2d\u660e\u6587\u7684\u9879\uff0c\u9010\u6761\u6807\u6ce8\uff09\n- **A1** \u4e3b\u94fe \u03c6/\u03c8 \u7684\u6807\u51c6\u539f\u5b50\u5b9a\u4e49\uff08\u6b8b\u57fa\u8303\u56f4\u89c1 \u00a72.1\uff09\u3002\n- **A2** \u4fa7\u94fe \u03c7 \u6309\u6c28\u57fa\u9178\u547d\u540d\u7684\u6b8b\u57fa\u76f8\u5173\u5b9a\u4e49\uff08\u6b8b\u57fa\u5e8f\u5217\u672a\u77e5\uff0c\u6545\u54ea\u4e9b \u03c7 \u5b58\u5728\u4ecd\u672a\u77e5\uff09\u3002\n- **A3** MD \u8f68\u8ff9\u7684\u6765\u6e90\u4e0e\u683c\u5f0f\uff08\u5047\u5b9a MD \u5e38\u89c1\u5e27\u683c\u5f0f + \u62d3\u6251/PDB\uff09\u3002\n- **A4** TICA \u7279\u5f81\u8f93\u5165\uff08\u9ed8\u8ba4 sin/cos \u5168\u90e8\u626d\u8f6c\uff1b\u5907\u9009\u91cd\u539f\u5b50\u8ddd\u79bb\uff09\u3002\n- **A5** TICA \u65f6\u6ede \u03c4\uff08\u9ed8\u8ba4\u53d6 MD \u8f93\u51fa\u6b65\u957f\u82e5\u5e72\u500d\uff0c\u505a\u654f\u611f\u6027\u68c0\u67e5\uff09\u3002\n- **A6** top TICA \u5206\u91cf\u6570 k=2~3\uff08